6|bufsize_t _scan_at(bufsize_t (*scanner)(const unsigned char *), cmark_chunk *c,
7|                   bufsize_t offset) {
8|  bufsize_t res;
9|  unsigned char *ptr = (unsigned char *)c->data;
10|
11|  if (ptr == NULL || offset > c->len) {
12|    return 0;
13|  } else {
14|    unsigned char lim = ptr[c->len];
15|
16|    ptr[c->len] = '\0';
17|    res = scanner(ptr + offset);
18|    ptr[c->len] = lim;
19|  }
20|
21|  return res;
22|}

