521|static cmark_node *finalize_document(cmark_parser *parser) {
522|  while (parser->current != parser->root) {
523|    parser->current = finalize(parser, parser->current);
524|  }
525|
526|  finalize(parser, parser->root);
527|
528|  // Limit total size of extra content created from reference links to
529|  // document size to avoid superlinear growth. Always allow 100KB.
530|  if (parser->total_size > 100000)
531|    parser->refmap->max_ref_size = parser->total_size;
532|  else
533|    parser->refmap->max_ref_size = 100000;
534|
535|  process_inlines(parser->mem, parser->root, parser->refmap, parser->options);
536|
537|  cmark_strbuf_free(&parser->content);
538|
539|  return parser->root;
540|}

