975|static void open_new_blocks(cmark_parser *parser, cmark_node **container,
976|                            cmark_chunk *input, bool all_matched) {
977|  bool indented;
978|  cmark_list *data = NULL;
979|  bool maybe_lazy = S_type(parser->current) == CMARK_NODE_PARAGRAPH;
980|  cmark_node_type cont_type = S_type(*container);
981|  bufsize_t matched = 0;
982|  int lev = 0;
983|  bool save_partially_consumed_tab;
984|  bool has_content;
985|  int save_offset;
986|  int save_column;
987|
988|  while (cont_type != CMARK_NODE_CODE_BLOCK &&
989|         cont_type != CMARK_NODE_HTML_BLOCK) {
990|
991|    S_find_first_nonspace(parser, input);
992|    indented = parser->indent >= CODE_INDENT;
993|
994|    if (!indented && peek_at(input, parser->first_nonspace) == '>') {
995|
996|      bufsize_t blockquote_startpos = parser->first_nonspace;
997|
998|      S_advance_offset(parser, input,
999|                       parser->first_nonspace + 1 - parser->offset, false);
1000|      // optional following character
1001|      if (S_is_space_or_tab(peek_at(input, parser->offset))) {
1002|        S_advance_offset(parser, input, 1, true);
1003|      }
1004|      *container = add_child(parser, *container, CMARK_NODE_BLOCK_QUOTE,
1005|                             blockquote_startpos + 1);
1006|
1007|    } else if (!indented && (matched = scan_atx_heading_start(
1008|                                 input, parser->first_nonspace))) {
1009|      bufsize_t hashpos;
1010|      int level = 0;
1011|      bufsize_t heading_startpos = parser->first_nonspace;
1012|
1013|      S_advance_offset(parser, input,
1014|                       parser->first_nonspace + matched - parser->offset,
1015|                       false);
1016|      *container = add_child(parser, *container, CMARK_NODE_HEADING,
1017|                             heading_startpos + 1);
1018|
1019|      hashpos = cmark_chunk_strchr(input, '#', parser->first_nonspace);
1020|
1021|      while (peek_at(input, hashpos) == '#') {
1022|        level++;
1023|        hashpos++;
1024|      }
1025|
1026|      (*container)->as.heading.level = level;
1027|      (*container)->as.heading.setext = false;
1028|      (*container)->as.heading.internal_offset = matched;
1029|
1030|    } else if (!indented && (matched = scan_open_code_fence(
1031|                                 input, parser->first_nonspace))) {
1032|      *container = add_child(parser, *container, CMARK_NODE_CODE_BLOCK,
1033|                             parser->first_nonspace + 1);
1034|      (*container)->as.code.fenced = true;
1035|      (*container)->as.code.fence_char = peek_at(input, parser->first_nonspace);
1036|      (*container)->as.code.fence_length = (matched > 255) ? 255 : matched;
1037|      (*container)->as.code.fence_offset =
1038|          (int8_t)(parser->first_nonspace - parser->offset);
1039|      (*container)->as.code.info = NULL;
1040|      S_advance_offset(parser, input,
1041|                       parser->first_nonspace + matched - parser->offset,
1042|                       false);
1043|
1044|    } else if (!indented && ((matched = scan_html_block_start(
1045|                                  input, parser->first_nonspace)) ||
1046|                             (cont_type != CMARK_NODE_PARAGRAPH &&
1047|                              !maybe_lazy &&
1048|                              (matched = scan_html_block_start_7(
1049|                                   input, parser->first_nonspace))))) {
1050|      *container = add_child(parser, *container, CMARK_NODE_HTML_BLOCK,
1051|                             parser->first_nonspace + 1);
1052|      (*container)->as.html_block_type = matched;
1053|      // note, we don't adjust parser->offset because the tag is part of the
1054|      // text
1055|    } else if (!indented && cont_type == CMARK_NODE_PARAGRAPH &&
1056|               (lev =
1057|                    scan_setext_heading_line(input, parser->first_nonspace))) {
1058|      // finalize paragraph, resolving reference links
1059|      has_content = resolve_reference_link_definitions(parser);
1060|
1061|      if (has_content) {
1062|
1063|        (*container)->type = (uint16_t)CMARK_NODE_HEADING;
1064|        (*container)->as.heading.level = lev;
1065|        (*container)->as.heading.setext = true;
1066|        S_advance_offset(parser, input, input->len - 1 - parser->offset, false);
1067|      }
