44|static int S_render_node(cmark_node *node, cmark_event_type ev_type,
45|                         struct render_state *state, int options) {
46|  cmark_node *parent;
47|  cmark_node *grandparent;
48|  cmark_strbuf *html = state->html;
49|  char start_heading[] = "<h0";
50|  char end_heading[] = "</h0";
51|  bool tight;
52|  char buffer[BUFFER_SIZE];
53|
54|  bool entering = (ev_type == CMARK_EVENT_ENTER);
55|
56|  if (state->plain == node) { // back at original node
57|    state->plain = NULL;
58|  }
59|
60|  if (state->plain != NULL) {
61|    switch (node->type) {
62|    case CMARK_NODE_TEXT:
63|    case CMARK_NODE_CODE:
64|    case CMARK_NODE_HTML_INLINE:
65|      escape_html(html, node->data, node->len);
66|      break;
67|
68|    case CMARK_NODE_LINEBREAK:
69|    case CMARK_NODE_SOFTBREAK:
70|      cmark_strbuf_putc(html, ' ');
71|      break;
72|
73|    default:
74|      break;
75|    }
76|    return 1;
77|  }
78|
79|  switch (node->type) {
80|  case CMARK_NODE_DOCUMENT:
81|    break;
82|
83|  case CMARK_NODE_BLOCK_QUOTE:
84|    if (entering) {
85|      cr(html);
86|      cmark_strbuf_puts(html, "<blockquote");
87|      S_render_sourcepos(node, html, options);
88|      cmark_strbuf_puts(html, ">\n");
89|    } else {
90|      cr(html);
91|      cmark_strbuf_puts(html, "</blockquote>\n");
92|    }
93|    break;
94|
95|  case CMARK_NODE_LIST: {
96|    cmark_list_type list_type = (cmark_list_type)node->as.list.list_type;
97|    int start = node->as.list.start;
98|
99|    if (entering) {
100|      cr(html);
101|      if (list_type == CMARK_BULLET_LIST) {
102|        cmark_strbuf_puts(html, "<ul");
103|        S_render_sourcepos(node, html, options);
104|        cmark_strbuf_puts(html, ">\n");
105|      } else if (start == 1) {
106|        cmark_strbuf_puts(html, "<ol");
107|        S_render_sourcepos(node, html, options);
108|        cmark_strbuf_puts(html, ">\n");
109|      } else {
110|        snprintf(buffer, BUFFER_SIZE, "<ol start=\"%d\"", start);
111|        cmark_strbuf_puts(html, buffer);
112|        S_render_sourcepos(node, html, options);
113|        cmark_strbuf_puts(html, ">\n");
114|      }
115|    } else {
116|      cmark_strbuf_puts(html,
117|                        list_type == CMARK_BULLET_LIST ? "</ul>\n" : "</ol>\n");
118|    }
119|    break;
120|  }
121|
122|  case CMARK_NODE_ITEM:
123|    if (entering) {
124|      cr(html);
125|      cmark_strbuf_puts(html, "<li");
126|      S_render_sourcepos(node, html, options);
127|      cmark_strbuf_putc(html, '>');
128|    } else {
129|      cmark_strbuf_puts(html, "</li>\n");
130|    }
131|    break;
132|
133|  case CMARK_NODE_HEADING:
134|    if (entering) {
135|      cr(html);
136|      start_heading[2] = (char)('0' + node->as.heading.level);
137|      cmark_strbuf_puts(html, start_heading);
138|      S_render_sourcepos(node, html, options);
139|      cmark_strbuf_putc(html, '>');
140|    } else {
141|      end_heading[3] = (char)('0' + node->as.heading.level);
142|      cmark_strbuf_puts(html, end_heading);
143|      cmark_strbuf_puts(html, ">\n");
144|    }
145|    break;
146|
147|  case CMARK_NODE_CODE_BLOCK:
148|    cr(html);
149|
150|    if (node->as.code.info == NULL || node->as.code.info[0] == 0) {
151|      cmark_strbuf_puts(html, "<pre");
152|      S_render_sourcepos(node, html, options);
153|      cmark_strbuf_puts(html, "><code>");
154|    } else {
155|      bufsize_t first_tag = 0;
156|      while (node->as.code.info[first_tag] &&
157|             !cmark_isspace(node->as.code.info[first_tag])) {
158|        first_tag += 1;
159|      }
160|
161|      cmark_strbuf_puts(html, "<pre");
162|      S_render_sourcepos(node, html, options);
163|      cmark_strbuf_puts(html, "><code class=\"");
164|      if (strncmp((char *)node->as.code.info, "language-", 9) != 0) {
165|        cmark_strbuf_puts(html, "language-");
166|      }
167|      escape_html(html, node->as.code.info, first_tag);
168|      cmark_strbuf_puts(html, "\">");
169|    }
170|
171|    escape_html(html, node->data, node->len);
172|    cmark_strbuf_puts(html, "</code></pre>\n");
173|    break;
174|
175|  case CMARK_NODE_HTML_BLOCK:
176|    cr(html);
177|    if (!(options & CMARK_OPT_UNSAFE)) {
178|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
179|    } else {
180|      cmark_strbuf_put(html, node->data, node->len);
181|    }
182|    cr(html);
183|    break;
184|
185|  case CMARK_NODE_CUSTOM_BLOCK: {
186|    unsigned char *block = entering ? node->as.custom.on_enter :
187|                                      node->as.custom.on_exit;
188|    cr(html);
189|    if (block) {
190|      cmark_strbuf_puts(html, (char *)block);
191|    }
192|    cr(html);
193|    break;
194|  }
195|
196|  case CMARK_NODE_THEMATIC_BREAK:
197|    cr(html);
198|    cmark_strbuf_puts(html, "<hr");
199|    S_render_sourcepos(node, html, options);
200|    cmark_strbuf_puts(html, " />\n");
201|    break;
202|
203|  case CMARK_NODE_PARAGRAPH:
204|    parent = cmark_node_parent(node);
205|    grandparent = cmark_node_parent(parent);
206|    if (grandparent != NULL && grandparent->type == CMARK_NODE_LIST) {
207|      tight = grandparent->as.list.tight;
208|    } else {
209|      tight = false;
210|    }
211|    if (!tight) {
212|      if (entering) {
213|        cr(html);
214|        cmark_strbuf_puts(html, "<p");
215|        S_render_sourcepos(node, html, options);
216|        cmark_strbuf_putc(html, '>');
217|      } else {
218|        cmark_strbuf_puts(html, "</p>\n");
219|      }
220|    }
221|    break;
222|
223|  case CMARK_NODE_TEXT:
224|    escape_html(html, node->data, node->len);
225|    break;
226|
227|  case CMARK_NODE_LINEBREAK:
228|    cmark_strbuf_puts(html, "<br />\n");
229|    break;
230|
231|  case CMARK_NODE_SOFTBREAK:
232|    if (options & CMARK_OPT_HARDBREAKS) {
233|      cmark_strbuf_puts(html, "<br />\n");
234|    } else if (options & CMARK_OPT_NOBREAKS) {
235|      cmark_strbuf_putc(html, ' ');
236|    } else {
237|      cmark_strbuf_putc(html, '\n');
238|    }
239|    break;
240|
241|  case CMARK_NODE_CODE:
242|    cmark_strbuf_puts(html, "<code>");
243|    escape_html(html, node->data, node->len);
244|    cmark_strbuf_puts(html, "</code>");
245|    break;
246|
247|  case CMARK_NODE_HTML_INLINE:
248|    if (!(options & CMARK_OPT_UNSAFE)) {
249|      cmark_strbuf_puts(html, "<!-- raw HTML omitted -->");
250|    } else {
251|      cmark_strbuf_put(html, node->data, node->len);
252|    }
253|    break;
254|
255|  case CMARK_NODE_CUSTOM_INLINE: {
256|    unsigned char *block = entering ? node->as.custom.on_enter :
257|                                      node->as.custom.on_exit;
258|    if (block) {
259|      cmark_strbuf_puts(html, (char *)block);
260|    }
261|    break;
262|  }
263|
264|  case CMARK_NODE_STRONG:
265|    if (entering) {
266|      cmark_strbuf_puts(html, "<strong>");
267|    } else {
268|      cmark_strbuf_puts(html, "</strong>");
269|    }
270|    break;
271|
272|  case CMARK_NODE_EMPH:
273|    if (entering) {
274|      cmark_strbuf_puts(html, "<em>");
275|    } else {
276|      cmark_strbuf_puts(html, "</em>");
277|    }
278|    break;
279|
280|  case CMARK_NODE_LINK:
281|    if (entering) {
282|      cmark_strbuf_puts(html, "<a href=\"");
283|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
284|                                !(_scan_dangerous_url(node->as.link.url)))) {
285|        houdini_escape_href(html, node->as.link.url,
286|                            (bufsize_t)strlen((char *)node->as.link.url));
287|      }
288|      if (node->as.link.title) {
289|        cmark_strbuf_puts(html, "\" title=\"");
290|        escape_html(html, node->as.link.title,
291|                    (bufsize_t)strlen((char *)node->as.link.title));
292|      }
293|      cmark_strbuf_puts(html, "\">");
294|    } else {
295|      cmark_strbuf_puts(html, "</a>");
296|    }
297|    break;
298|
299|  case CMARK_NODE_IMAGE:
300|    if (entering) {
301|      cmark_strbuf_puts(html, "<img src=\"");
302|      if (node->as.link.url && ((options & CMARK_OPT_UNSAFE) ||
303|                                !(_scan_dangerous_url(node->as.link.url)))) {
304|        houdini_escape_href(html, node->as.link.url,
305|                            (bufsize_t)strlen((char *)node->as.link.url));
306|      }
307|      cmark_strbuf_puts(html, "\" alt=\"");
308|      state->plain = node;
309|    } else {
310|      if (node->as.link.title) {
311|        cmark_strbuf_puts(html, "\" title=\"");
312|        escape_html(html, node->as.link.title,
313|                    (bufsize_t)strlen((char *)node->as.link.title));
314|      }
315|
316|      cmark_strbuf_puts(html, "\" />");
317|    }
318|    break;
319|
320|  default:
321|    assert(false);
322|    break;
323|  }
324|
325|  // cmark_strbuf_putc(html, 'x');
326|  return 1;
327|}

