894|static cmark_node *check_open_blocks(cmark_parser *parser, cmark_chunk *input,
895|                                     bool *all_matched) {
896|  bool should_continue = true;
897|  *all_matched = false;
898|  cmark_node *container = parser->root;
899|  cmark_node_type cont_type;
900|
901|  while (S_last_child_is_open(container)) {
902|    container = container->last_child;
903|    cont_type = S_type(container);
904|
905|    S_find_first_nonspace(parser, input);
906|
907|    switch (cont_type) {
908|    case CMARK_NODE_BLOCK_QUOTE:
909|      if (!parse_block_quote_prefix(parser, input))
910|        goto done;
911|      break;
912|    case CMARK_NODE_LIST:
913|      // Avoid quadratic behavior caused by iterating deeply nested lists
914|      // for each blank line.
915|      if (parser->blank) {
916|        if (container->flags & CMARK_NODE__LIST_LAST_LINE_BLANK &&
917|            parser->indent == 0) {
918|          // Abort early if we encounter multiple blank lines. Returning
919|          // NULL will cause S_process_line to skip the calls to
920|          // open_new_blocks and add_text_to_container. open_new_blocks
921|          // is a no-op for blank lines. add_text_to_container closes
922|          // remaining open nodes, but since we have a second blank
923|          // line, all open nodes have already been closed when the
924|          // first blank line was processed. Certain block types accept
925|          // empty lines as content, so add them here.
926|          if (parser->current->type == CMARK_NODE_CODE_BLOCK ||
927|              parser->current->type == CMARK_NODE_HTML_BLOCK) {
928|            add_line(input, parser);
929|          }
930|          return NULL;
931|        }
932|        container->flags |= CMARK_NODE__LIST_LAST_LINE_BLANK;
933|      } else {
934|        container->flags &= ~CMARK_NODE__LIST_LAST_LINE_BLANK;
935|      }
936|      break;
937|    case CMARK_NODE_ITEM:
938|      if (!parse_node_item_prefix(parser, input, container))
939|        goto done;
940|      break;
941|    case CMARK_NODE_CODE_BLOCK:
942|      if (!parse_code_block_prefix(parser, input, container, &should_continue))
943|        goto done;
944|      break;
945|    case CMARK_NODE_HEADING:
946|      // a heading can never contain more than one line
947|      goto done;
948|    case CMARK_NODE_HTML_BLOCK:
949|      if (!parse_html_block_prefix(parser, container))
950|        goto done;
951|      break;
952|    case CMARK_NODE_PARAGRAPH:
953|      if (parser->blank)
954|        goto done;
955|      break;
956|    default:
957|      break;
958|    }
959|  }
960|
961|  *all_matched = true;
962|
963|done:
964|  if (!*all_matched) {
965|    container = container->parent; // back up to last matching node
966|  }
967|
968|  if (!should_continue) {
969|    container = NULL;
970|  }
971|
972|  return container;
973|}

